 private void startApprovedServices(){UpdateService.initialize(this);if(dead||startupStarted||!RiskNotice.accepted(this))return;if(!RuntimeSettings.open(this)){Toast.makeText(this,"无法保存运行设置，请检查星匣的存储空间后重试",1).show();return;}startupStarted=true;AppLog.record(getFilesDir(),"程序","已打开星匣");syncRuntimeOptions();RootAccess.resetRecovery();prepareBridge();refresh();getSharedPreferences("connection",0).edit().putBoolean("appActive",true).apply();startForegroundService(new Intent(this,ConsoleService.class));PhoneCompanion.attach(this);checkBridgeOnResume();sessionHandler.removeCallbacks(sessionTick);sessionHandler.post(sessionTick);if(RuntimeSettings.snapshot(this).keepAlive&&getSharedPreferences("connection",0).getBoolean("overlay",true)&&!android.provider.Settings.canDrawOverlays(this))Toast.makeText(this,"请在【后台】中打开悬浮窗权限",1).show();if(getSharedPreferences("updates",0).getBoolean("auto",true))UpdateService.check(this,false);RemoteStartController.onApplicationOpen(this);}
