 private void showPhone(){PhoneCompanion.refresh();if(PhoneCompanion.connected()){Toast.makeText(this,"已连接",0).show();return;}List<NetworkState.Address> list=NetworkState.list();if(list.isEmpty()){Toast.makeText(this,"未发现局域网地址，请连接 Wi-Fi 或开启热点",1).show();return;}
  android.app.Dialog dialog=new android.app.Dialog(this);dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);LinearLayout body=column();body.setPadding(dp(28),dp(22),dp(28),dp(22));body.setBackground(surface(Design.CARD,24));body.setClipToOutline(true);TextView title=Design.text(this,"手机助手",26);title.setGravity(android.view.Gravity.CENTER);body.addView(title);TextView help=Design.text(this,"手机连接同一网络，扫码后输入四位连接码",18);help.setGravity(android.view.Gravity.CENTER);body.addView(help);Spinner choices=new Spinner(this);List<String> labels=new ArrayList<>();for(NetworkState.Address n:list)labels.add(n.label());choices.setAdapter(new UiAdapter(this,labels));body.addView(choices);QrView qr=new QrView(this,PhoneCompanion.url(list.get(0).ip));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(dp(230),dp(230));qp.gravity=android.view.Gravity.CENTER_HORIZONTAL;qp.topMargin=dp(10);qp.bottomMargin=dp(10);body.addView(qr,qp);TextView info=Design.text(this,"",21);info.setGravity(android.view.Gravity.CENTER);info.setTextIsSelectable(true);body.addView(info);TextView tip=Design.text(this,"也可在手机浏览器输入网址。连接成功后本弹窗会自动关闭。",16);tip.setGravity(android.view.Gravity.CENTER);body.addView(tip);Button close=Design.button(this,"关闭",dialog::dismiss);close.setBackground(Design.feedback(this,Design.ACCENT,12));close.setTextColor(Design.BG);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(230),dp(56));cp.gravity=android.view.Gravity.CENTER_HORIZONTAL;cp.topMargin=dp(16);body.addView(close,cp);dialog.setContentView(body);dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams attr=dialog.getWindow().getAttributes();attr.dimAmount=.58f;dialog.getWindow().setAttributes(attr);dialog.show();dialog.getWindow().setLayout(Math.min(dp(780),(int)(getResources().getDisplayMetrics().widthPixels*.88)),-2);
  Runnable update=()->{if(list.isEmpty())return;int selected=Math.max(0,Math.min(list.size()-1,choices.getSelectedItemPosition()));String url=PhoneCompanion.url(list.get(selected).ip);qr.setUrl(url);info.setText(url+"\n连接码："+PhoneCompanion.pin());};choices.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){update.run();}});update.run();dialog.setOnDismissListener(d->phoneRefresh=null);phoneRefresh=()->{if(PhoneCompanion.connected()){dialog.dismiss();Toast.makeText(this,"已连接",0).show();return;}List<NetworkState.Address> fresh=NetworkState.list();StringBuilder before=new StringBuilder(),after=new StringBuilder();for(NetworkState.Address a:list)before.append(a.label());for(NetworkState.Address a:fresh)after.append(a.label());if(!before.toString().equals(after.toString())){list.clear();list.addAll(fresh);List<String> values=new ArrayList<>();for(NetworkState.Address a:list)values.add(a.label());if(values.isEmpty())values.add("暂无局域网地址");choices.setAdapter(new UiAdapter(this,values));}if(list.isEmpty()){qr.setUrl("");info.setText("网络已断开，请连接 Wi-Fi 或开启热点");}else update.run();};}
 private void copyFallbackAuthorization(){if(probing||endingAuthorization||RootAccess.busy()){Toast.makeText(this,"正在处理授权，请稍后重试",0).show();return;}try{prepareBridge();File secretFile=new File(getFilesDir(),"bridge-token");RootPermit.Ticket lease=RootAccess.fallbackPermit(this);RootAuthorization.prepare(this,secretFile,lease);String command="sh "+UpdateTask.quote(new File(getFilesDir(),"root-authorize.sh").getCanonicalPath());PhoneCompanion.copy(this,"root-authorization",command,true);AppLog.record(getFilesDir(),"提权","已复制临时提权命令，等待授权工具执行");RootInstructions.show(this);}catch(Exception failed){AppLog.record(getFilesDir(),"提权","临时提权命令复制失败");Toast.makeText(this,"复制失败："+UserMessages.explain(failed),1).show();}}
 private void showLogs(){String content=AppLog.read(getFilesDir());TextView text=Design.text(this,content,17);text.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(text);scroll.setPadding(dp(18),dp(8),dp(18),dp(8));Design.show(new android.app.AlertDialog.Builder(this).setTitle("日志 · 最多保留7天").setView(scroll).setNegativeButton("关闭",null).setPositiveButton("复制日志",(d,which)->{try{PhoneCompanion.copy(this,"logs",content,false);Toast.makeText(this,"日志已复制",0).show();}catch(Exception failed){Toast.makeText(this,"复制失败，请重试",1).show();}}));}
 private void prepareBridge(){try{File secretFile=new File(getFilesDir(),"bridge-token");if(!secretFile.exists()){byte[] random=new byte[16];new SecureRandom().nextBytes(random);StringBuilder b=new StringBuilder();for(byte n:random)b.append(String.format(Locale.US,"%02x",n&255));try(FileOutputStream out=new FileOutputStream(secretFile)){out.write(b.toString().getBytes("US-ASCII"));}}
  byte[] bytes=new byte[32];try(FileInputStream in=new FileInputStream(secretFile)){int offset=0,n;while(offset<32&&(n=in.read(bytes,offset,32-offset))>0)offset+=n;if(offset!=32)throw new IOException("授权信息异常，请重新打开星匣后重试");}bridgeSecret=new String(bytes,"US-ASCII");
  RootAccess.init(this);
 }catch(Exception e){String message="无法读取授权信息："+UserMessages.explain(e);output.setText(message);setRootMessage(message);}}
 private void refresh(){String old="";if(!ips.isEmpty()&&addresses.getSelectedItemPosition()<ips.size())old=ips.get(addresses.getSelectedItemPosition());networks.clear();networks.addAll(NetworkState.list());ips.clear();List<String> labels=new ArrayList<>();int selected=0;String peer=appliedIp;NetworkState.Address best=NetworkState.maintained(networks,peer,getSharedPreferences("connection",0).getString("adbInterface",""));for(int i=0;i<networks.size();i++){NetworkState.Address a=networks.get(i);ips.add(a.ip);labels.add(a.label());if(a.ip.equals(old)||a==best)selected=i;}if(labels.isEmpty()){labels.add("暂无局域网地址，请连接 Wi-Fi 或开启热点");networkStatus.setTextColor(Design.YELLOW);networkStatus.setText("暂无局域网地址，内网穿透仍可使用");}ArrayAdapter<String> adapter=new UiAdapter(this,labels,networks.isEmpty());adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);addresses.setAdapter(adapter);addresses.setSelection(selected);}
 private void refreshNetworkIfChanged(){List<NetworkState.Address> now=NetworkState.list();StringBuilder fresh=new StringBuilder(),old=new StringBuilder();for(NetworkState.Address a:now)fresh.append(a.label());for(NetworkState.Address a:networks)old.append(a.label());if(!fresh.toString().equals(old.toString())){refresh();if(rootAvailable||server!=null)readAdb();}}
 private String adbInterface(){if(networks.isEmpty())throw new IllegalArgumentException("请刷新网络地址");return networks.get(addresses.getSelectedItemPosition()).iface;}
 private void probe(){if(probing||endingAuthorization||RootAccess.busy()){Toast.makeText(this,"正在处理授权或执行 Root 命令，请稍后重试",0).show();return;}probing=true;probeButton.setEnabled(false);rootToggle.setChecked(false);rootToggle.setAllowed(false);setRootMessage("正在检测 Root 授权，请留意授权提示（最长 45 秒）…");new Thread(()->{CommandRunner.Result r=RootAccess.check(this,true);if(!dead)runOnUiThread(()->{if(endingAuthorization)return;probing=false;probeButton.setEnabled(true);bridgeMode=RootAccess.bridge();setRootAvailable(RootAccess.available());setRootMessage(rootAvailable?"Root 授权可用。需要在网页执行 Root 命令时，请勾选命令回传中的 Root 选项。":"尚未获得 Root 授权。可启用独立授权，或复制临时提权命令到 EVCC／应用管家执行。");output.setText("退出码："+r.exit+"\n标准输出：\n"+r.stdout+"\n错误输出：\n"+r.stderr+"\n"+r.error);readAdb();});},"root-probe").start();}
 private void startServer(){syncSession();if(server!=null||probing||endingAuthorization){Toast.makeText(this,"请先停止命令回传，或等待检测完成",0).show();return;}boolean allowRoot=rootToggle.isChecked();String host=ips.isEmpty()?"":ips.get(addresses.getSelectedItemPosition());if(!networks.isEmpty())getSharedPreferences("connection",0).edit().putString("consoleInterface",adbInterface()).apply();probing=true;startButton.setEnabled(false);probeButton.setEnabled(false);rootToggle.setAllowed(false);new Thread(()->{String failure="";try{if(allowRoot)RootAccess.check(this,false);ConsoleService.startSession(this,host,allowRoot);}catch(Exception e){failure=UserMessages.explain(e);}String error=failure;if(!dead)runOnUiThread(()->{probing=false;setRootAvailable(RootAccess.available());if(error.isEmpty())syncSession();else{sessionError.setText("启动失败："+error);sessionError.setVisibility(0);startButton.setEnabled(true);probeButton.setEnabled(true);}});},"start-console").start();}
 private void stopServer(){sessionError.setVisibility(8);ConsoleService.endSession();if(!ConsoleService.active(this))stopService(new Intent(this,ConsoleService.class));server=null;sessionUrl="";token="";sessionState.setText("回传已停止；旧连接码已作废");sessionHeading.state(false);setRootMessage(RootAccess.available()?"Root 授权可用，可勾选网页 Root 命令后重新启动回传。":"尚未获得有效 Root 授权，请重新授权。");addresses.setEnabled(true);rootToggle.setChecked(false);setRootAvailable(RootAccess.available());startButton.setEnabled(!probing);probeButton.setEnabled(!probing);}
 private void setStable(TextView view,String value){if(!view.getText().toString().equals(value))view.setText(value);}
