 private void requestOverlayPermission(){
  if(android.provider.Settings.canDrawOverlays(this)){Toast.makeText(this,"已具有悬浮窗权限，无需再次授权",1).show();return;}
  Intent[] routes={new Intent(android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+getPackageName())),new Intent(android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION),new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))};
  for(Intent route:routes){try{if(route.resolveActivity(getPackageManager())!=null){startActivity(route);return;}}catch(android.content.ActivityNotFoundException|SecurityException unavailable){/* Some car firmware removes or restricts Android settings activities. */}}
  Design.show(new android.app.AlertDialog.Builder(this).setTitle("车机未提供悬浮窗授权入口").setMessage("请在车机的应用管理或权限管理中，为E02星匣开启悬浮窗权限，再返回本程序。若系统没有此选项，可使用你已有的权限管理工具。\n\n未授权时，手机助手等服务仍可使用，保活悬浮窗暂不显示。").setPositiveButton("明白",null));
 }
