 private void confirmInitialization(){
  android.app.AlertDialog d=new android.app.AlertDialog.Builder(this).setTitle("初始化 E02星匣？").setMessage("将清除星匣的所有配置、设置、连接凭证和首次使用确认记录，并停止手机助手、命令回传、内网穿透和本次 Root 提权。此操作无法撤销。\n\n初始化后程序会关闭。请重新打开 E02星匣，查看首次启动的免责声明与风险告知，并重新配置所需功能。\n\n不会恢复车机出厂设置，也不会修改当前系统 ADB 设置；下载文件夹里的截图会保留。").setNegativeButton("取消",null).setPositiveButton("确认初始化",(dialog,which)->initializeApplication()).create();
  d.setOnShowListener(v->{Design.dialog(d);Design.actionColor(d.getButton(android.app.AlertDialog.BUTTON_POSITIVE),false);});d.show();
 }
 private void initializeApplication(){if(displayTrialBusy())return;
  if(parkingExitBlocked())return;
  if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再初始化",1).show();return;}if(dead)return;RuntimeRecovery.cancel();RootAccess.beginRevoke();dead=true;sessionHandler.removeCallbacksAndMessages(null);NumberPad.dismiss();PhoneCompanion.stop();UpdateService.cancel();RemoteService.stop(this);stopService(new Intent(this,UpdateService.class));
  new Thread(()->{try{
   ConsoleService.endSession();String secret=exitBridgeToken();CommandRunner.Result stopped=RootAccess.stop(this,true);if(!stopped.error.isEmpty())throw new IOException(stopped.error);if(!StatusBarEntry.disableForExit(this))throw new IOException(StatusBarEntry.error);
   if(!secret.isEmpty()){CommandRunner.Result check=new BridgeRunner(secret,false).execute("id",true,2);if(check.exit==0&&!check.timedOut&&check.stdout.matches("(?s).*\\buid=0\\(root\\).*"))throw new IOException("Root 提权尚未停止，请稍后重试");}
   stopService(new Intent(this,ConsoleService.class));
   android.app.ActivityManager manager=(android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE);
   if(manager==null||!manager.clearApplicationUserData())throw new IOException("系统未允许初始化，请在车机应用管理中清除星匣的数据");
  }catch(Exception e){runOnUiThread(()->{RootAccess.finishRevoke();dead=false;Toast.makeText(this,"初始化未完成："+UserMessages.explain(e),Toast.LENGTH_LONG).show();recreate();});}},"starbox-initialize").start();
 }
 private String exitBridgeToken(){if(!bridgeSecret.isEmpty())return bridgeSecret;try{byte[] bytes=new byte[32];try(DataInputStream in=new DataInputStream(new FileInputStream(new File(getFilesDir(),"bridge-token")))){in.readFully(bytes);if(in.read()!=-1)return "";}String secret=new String(bytes,"US-ASCII");return secret.matches("[0-9a-f]{32}")?secret:"";}catch(IOException ignored){return "";}}
 private CheckBox runtimeToggle(LinearLayout row,String name){CheckBox option=new CheckBox(this);option.setText(name);styleToggle(option);option.setTextSize(18);row.addView(option,new LinearLayout.LayoutParams(0,dp(54),1));option.setOnCheckedChangeListener((view,on)->saveRuntimeOptions());return option;}
 private final Runnable systemKeepAliveChanged=()->{if(!dead)syncRuntimeOptions();};
 private boolean auxiliaryBusy;
 private void showSystemKeepAlive(){
  if(!RuntimeSettings.snapshot(this).keepAlive){Toast.makeText(this,"请先开启星匣后台保活",1).show();return;}
  if(auxiliaryBusy){Toast.makeText(this,"正在准备恢复服务，请稍候",0).show();return;}
  boolean complete=SystemKeepAlive.enabled(this)&&SystemKeepAlive.requested(this)&&SystemKeepAlive.automatic(this)&&RootAccess.wakeReady();
  android.app.AlertDialog.Builder dialog=new android.app.AlertDialog.Builder(this).setTitle("系统辅助保活").setMessage("帮助星匣在车辆自然唤醒后恢复后台。启用后，在已有 Root 授权有效、相关功能仍开启时，可修复星匣自己的辅助保活授权，保留其他应用设置。\n\n不开启界面读取、触摸控制或按键过滤，不修改原厂供电。开机恢复还需勾选【开机自启】；断电或深睡眠期间不能保证远程可达。\n\n在星匣内停用此功能后不再修复；结束提权或主动退出会停止相应恢复。\n\n当前状态："+SystemKeepAlive.state(this)).setNegativeButton("取消",null);
  if(complete)dialog.setPositiveButton("停用辅助保活",(d,w)->disableSystemKeepAlive());
  else{dialog.setPositiveButton("启用并修复",(d,w)->enableSystemKeepAlive());if(SystemKeepAlive.requested(this))dialog.setNeutralButton("停用辅助保活",(d,w)->disableSystemKeepAlive());}
  Design.show(dialog);
 }
 private void disableSystemKeepAlive(){if(!SystemKeepAlive.disable(this))Toast.makeText(this,"设置未保存，请重试",1).show();else Toast.makeText(this,"已停用系统辅助保活",0).show();syncRuntimeOptions();}
 private void enableSystemKeepAlive(){
  if(!SystemKeepAlive.prepare(this)){Toast.makeText(this,"无法保存保活设置，请查看日志后重试",1).show();return;}
  if(!RootAccess.available()){
   try{startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS));}
   catch(RuntimeException unavailable){Design.show(new android.app.AlertDialog.Builder(this).setTitle("需要 Root 授权").setMessage("车机没有可打开的系统授权页面。请先启用独立 Root 授权，再返回后台页面启用系统辅助保活。").setPositiveButton("明白",null));}return;
  }
  auxiliaryBusy=true;if(systemKeepAliveButton!=null)systemKeepAliveButton.setEnabled(false);
  new Thread(()->{String result;
   try{
    CommandRunner.Result prepared=RootAccess.prepareWakeByUser(this);if(!prepared.error.isEmpty())throw new IOException(prepared.error);
    RootPermit.Ticket permit=RootPermit.active(getFilesDir());if(permit==null)throw new IOException("Root 授权已失效，请重新检测");
    String command="CLASSPATH="+UpdateTask.quote(getApplicationInfo().sourceDir)+" /system/bin/app_process /system/bin com.e02.rootconsole.AuxiliarySetupWorker "+UpdateTask.quote(getFilesDir().getCanonicalPath())+" "+UpdateTask.quote(permit.nonce);
    CommandRunner runner=RootAccess.runner(this);CommandRunner.Result response;try{response=runner.execute(command,true,40);}finally{runner.close();}
    if(response.exit==0&&!response.timedOut&&response.error.isEmpty())result="授权设置已完成，正在等待系统绑定";
    else if(response.stdout.contains("MASTER_OFF"))result="系统无障碍总开关已关闭，请在系统授权页面中开启；星匣没有修改该开关";
    else if(response.stdout.contains("DENIED"))result="当前未满足恢复条件，请确认屏幕已唤醒、后台保活和 Root 授权仍有效";
    else result="辅助保活未启用，请查看日志后重试";
   }catch(Exception failed){result="辅助保活未启用："+UserMessages.explain(failed);}
   final String message=result;runOnUiThread(()->{auxiliaryBusy=false;if(dead)return;syncRuntimeOptions();Design.show(new android.app.AlertDialog.Builder(this).setTitle("系统辅助保活").setMessage(SystemKeepAliveService.connected()&&RootAccess.wakeReady()?"系统已绑定星匣，辅助保活已启用":message).setPositiveButton("明白",null));});
  },"starbox-auxiliary-setup").start();
 }
 private void syncRuntimeOptions(){RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);boolean healthy=RuntimeSettings.healthy(this);syncingRuntime=true;for(CheckBox option:new CheckBox[]{keepAliveToggle,autoStartToggle})if(option!=null)option.setEnabled(healthy);if(keepAliveToggle!=null)keepAliveToggle.setChecked(state.keepAlive);if(autoStartToggle!=null)autoStartToggle.setChecked(state.autoStart);syncingRuntime=false;if(systemKeepAliveButton!=null){systemKeepAliveButton.setEnabled(healthy&&state.keepAlive&&!auxiliaryBusy);systemKeepAliveButton.setText("系统辅助保活");if(systemKeepAliveState!=null){String auxiliaryState=SystemKeepAlive.state(this);systemKeepAliveState.setText(auxiliaryState);systemKeepAliveState.setTextColor("已启用".equals(auxiliaryState)?Design.GREEN:"未启用".equals(auxiliaryState)?Design.MUTED:Design.YELLOW);}}if(quitButton!=null)ExitConfirm.style(quitButton,!healthy||parkingActiveForExit()||ExitPolicy.blocked(state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this)));syncKeepAliveChildren();}
 private void saveRuntimeOptions(){if(syncingRuntime||keepAliveToggle==null||autoStartToggle==null)return;boolean saved=RuntimeSettings.configure(this,keepAliveToggle.isChecked(),autoStartToggle.isChecked(),RuntimeSettings.snapshot(this).parkedRemote);syncRuntimeOptions();if(!saved)Toast.makeText(this,"设置未保存，请检查星匣的存储空间后重试",1).show();else{SystemKeepAlive.syncOptions(this);StatusBarEntry.sync(this);syncKeepAliveChildren();RuntimeRecovery.cancel();startForegroundService(new Intent(this,ConsoleService.class).setAction("options"));}}
 private void syncKeepAliveChildren(){
  if(statusBarToggle==null||overlayToggle==null)return;syncingChildren=true;boolean enabled=RuntimeSettings.healthy(this)&&RuntimeSettings.snapshot(this).keepAlive;
  statusBarToggle.setChecked(StatusBarEntry.selected(this));overlayToggle.setChecked(getSharedPreferences("connection",0).getBoolean("overlay",true));boolean invisible=getSharedPreferences("connection",0).getBoolean("invisibleOverlay",false);if(invisibleOverlayToggle!=null){invisibleOverlayToggle.setChecked(invisible);invisibleOverlayToggle.setEnabled(enabled&&overlayToggle.isChecked());}statusBarToggle.setEnabled(enabled);overlayToggle.setEnabled(enabled);overlayPermissionButton.setEnabled(enabled&&overlayToggle.isChecked());overlayCenterButton.setEnabled(enabled&&overlayToggle.isChecked()&&!invisible);
  keepAliveChildHint.setText(!enabled?"开启星匣后台保活后可使用下方选项，原有选择会保留。":!overlayToggle.isChecked()?"开启保活悬浮窗后，可选择无感悬浮窗。":!StatusBarEntry.error.isEmpty()?StatusBarEntry.error:invisible?"无感模式不显示内容、不响应触摸；需要截图或拖动时，请关闭无感悬浮窗。保活不阻止车机休眠。":"悬浮窗贴近边缘、拖不动时，可恢复到屏幕中央。状态栏入口由系统加载，不阻止车机休眠。");syncingChildren=false;
 }
 private void saveInvisibleOverlay(boolean on){if(syncingChildren)return;SharedPreferences prefs=getSharedPreferences("connection",0);boolean before=prefs.getBoolean("invisibleOverlay",false);if(!prefs.edit().putBoolean("invisibleOverlay",on).commit()){prefs.edit().putBoolean("invisibleOverlay",before).commit();Toast.makeText(this,"悬浮窗设置未保存，请重试",1).show();}syncKeepAliveChildren();startForegroundService(new Intent(this,ConsoleService.class).setAction("options"));}
 private void saveKeepAliveChild(boolean statusBar,boolean on){
  if(syncingChildren)return;boolean saved;if(statusBar)saved=StatusBarEntry.select(this,on);else{SharedPreferences prefs=getSharedPreferences("connection",0);boolean before=prefs.getBoolean("overlay",true);saved=prefs.edit().putBoolean("overlay",on).commit();if(!saved)prefs.edit().putBoolean("overlay",before).commit();}syncKeepAliveChildren();
  if(!saved){Toast.makeText(this,statusBar?StatusBarEntry.error:"悬浮窗设置未保存，请重试",1).show();return;}
  startForegroundService(new Intent(this,ConsoleService.class).setAction("options"));if(!statusBar&&on&&!android.provider.Settings.canDrawOverlays(this))requestOverlayPermission();
 }
 private void showExitRestriction(){RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);if(exitDialog!=null&&exitDialog.isShowing())return;exitDialog=ExitConfirm.show(this,state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this),()->selectPage(2));exitDialog.setOnDismissListener(dialog->exitDialog=null);}
 private boolean displayTrialBusy(){if(!DisplayTrialEntry.busy())return false;Design.show(new android.app.AlertDialog.Builder(this).setTitle("显示试验进行中").setMessage("请先停止显示试验并核对恢复结果，再退出、结束提权、安装更新或初始化。这样可以避免中断原路名恢复。") .setNegativeButton("留在当前页面",null).setPositiveButton("前往显示试验",(d,w)->selectPage(4)));return true;}
 private void requestExit(){if(displayTrialBusy())return;if(dead||parkingExitBlocked())return;syncRuntimeOptions();if(!RuntimeSettings.healthy(this)){Design.show(new android.app.AlertDialog.Builder(this).setTitle("暂时无法退出").setMessage("无法读取保活设置，请重新打开星匣后重试。").setPositiveButton("明白",null));return;}RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);if(ExitPolicy.blocked(state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this))){showExitRestriction();return;}if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再退出",1).show();return;}RuntimePolicy.Decision decision=RuntimeSettings.requestExit(this);if(decision.has(RuntimePolicy.Effect.EXIT_BLOCKED)){syncRuntimeOptions();showExitRestriction();return;}if(decision.has(RuntimePolicy.Effect.SAVE_ERROR))Toast.makeText(this,"运行设置保存失败，程序将关闭；下次打开后请检查设置",1).show();exitApplication();}
 private void exitAfterDecliningRisk(){if(RiskNotice.accepted(this))return;exitApplication();}
 private void exitApplication(){if(displayTrialBusy())return;if(dead||RiskNotice.accepted(this)&&parkingExitBlocked())return;if(RiskNotice.accepted(this)){RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);if(ExitPolicy.blocked(state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this))){syncRuntimeOptions();showExitRestriction();return;}}if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再退出",1).show();return;}RuntimeRecovery.cancel();RootAccess.beginRevoke();dead=true;sessionHandler.removeCallbacksAndMessages(null);PhoneCompanion.stop();getSharedPreferences("connection",0).edit().putBoolean("appActive",false).putBoolean("adbManaged",false).apply();UpdateService.cancel();RemoteService.stop(this);stopService(new Intent(this,UpdateService.class));new Thread(()->{ConsoleService.endSession();CommandRunner.Result stopped=RootAccess.stop(this,false);if(!StatusBarEntry.disableForExit(this)&&stopped.error.isEmpty())stopped.error=StatusBarEntry.error;stopService(new Intent(this,ConsoleService.class));if(!stopped.error.isEmpty()){RootAccess.finishRevoke();runOnUiThread(()->{dead=false;setRootAvailable(false);setRootMessage(stopped.error);Toast.makeText(this,"退出未完成："+stopped.error,1).show();});return;}runOnUiThread(()->{finishAndRemoveTask();new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(()->android.os.Process.killProcess(android.os.Process.myPid()),400);});},"starbox-exit").start();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==RemotePanel.IMPORT&&result==RESULT_OK&&data!=null&&data.getData()!=null)remotePanel.importUri(data.getData());}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(!RiskNotice.accepted(this)||dead)return;if(getSharedPreferences("updates",0).getBoolean("auto",true))UpdateService.check(this,false);}
 @Override protected void onResume(){super.onResume();visible=true;SystemKeepAlive.watch(systemKeepAliveChanged);syncRuntimeOptions();if(!RiskNotice.accepted(this)||dead)return;PhoneCompanion.attach(this);refreshNetworkIfChanged();syncSession();checkBridgeOnResume();if(server!=null)readAdb();sessionHandler.removeCallbacks(sessionTick);sessionHandler.post(sessionTick);}
 @Override public void onBackPressed(){if(!NumberPad.dismiss())super.onBackPressed();}
 @Override protected void onStop(){NumberPad.dismiss();PhoneCompanion.detach(this);sessionHandler.removeCallbacks(sessionTick);super.onStop();}
