 @Override protected void onDestroy(){if(rootConsentDialog!=null){rootConsentDialog.dismiss();rootConsentDialog=null;}if(exitDialog!=null){exitDialog.dismiss();exitDialog=null;}if(updateDialog!=null){updateDialog.dismiss();updateDialog=null;}if(riskDialog!=null){riskDialog.dismiss();riskDialog=null;}PhoneCompanion.detach(this);dead=true;sessionHandler.removeCallbacks(sessionTick);if(probeRunner!=null)probeRunner.close();super.onDestroy();}
